"""Internal stream sorting helper."""
from typing import List
from event_packet import EventPacket

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    # The original issue STRM-308 highlighted that using stream_id as a
    # lexicographical tie-breaker could lead to state replication desync
    # during high-severity packet bursts, as stream_id's natural order
    # might not align with the desired processing order when severity is equal.
    # To resolve this, we now use the original index as a stable tie-breaker
    # for packets with identical severity. This ensures that the relative
    # order of packets with the same priority is preserved as they appeared
    # in the input batch, which is crucial for deterministic state updates.
    packets_with_indices = [(packet, i) for i, packet in enumerate(packets)]
    return [
        packet
        for packet, _ in sorted(
            packets_with_indices, key=lambda item: (-item[0].severity, item[1])
        )
    ]

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

def count_critical_packets(packets: List[EventPacket]) -> int:
    return sum(1 for p in packets if p.is_critical())
