"""Internal stream sorting helper."""
from typing import List
from event_packet import EventPacket

def order_packets(packets: List[EventPacket]) -> List[EventPacket]:
    # Sort packets primarily by severity (descending).
    # For tie-breaking packets with the same severity, use the original insertion order
    # by leveraging Python's stable sort, rather than an arbitrary field like stream_id.
    # This prevents 'out-of-order stream tiebreaker' issues that can cause state desync
    # when packets from different streams have identical priority and the previous tiebreaker
    # (stream_id) led to an inconsistent global ordering.
    return sorted(packets, key=lambda p: -p.severity)

def get_max_severity(packets: List[EventPacket]) -> int:
    return max((p.severity for p in packets), default=0)

