"""Domain exception specifications."""
from typing import Dict, Any, Optional

class ServiceError(Exception):
    def __init__(self, code: str, message: str = "", details: Optional[Dict[str, Any]] = None):
        super().__init__(f"[{code}] {message}")
        self.code = code
        self.message = message
        self.details = details or {}

    def to_dict(self) -> Dict[str, Any]:
        return {"code": self.code, "message": self.message, "details": self.details}

class LockConflictError(ServiceError):
    """Exception raised when an attempt is made to acquire a lock on a resource already held by another owner."""
    def __init__(self, resource_id: str, conflicting_owner_id: str, message: str = "Resource is locked"):
        super().__init__(
            code="LOCK_CONFLICT",
            message=f"{message}: Resource '{resource_id}' is held by '{conflicting_owner_id}'",
            details={"resource_id": resource_id, "conflicting_owner_id": conflicting_owner_id}
        )
        self.resource_id = resource_id
        self.conflicting_owner_id = conflicting_owner_id
